# Define the function h'(z)
def h_prime(z):
    # Handle potential division by zero/domain issues near z = +/- 1, although fsolve usually handles this if started properly.
    if abs(z) >= 1:
        # For safety, return a large value if outside the open interval (-1, 1)
        return np.inf * np.sign(z)

    term1 = 5/2 - 27/2 * z**2
    term2 = 2 * np.sqrt(2) * z / np.sqrt(1 - z**2)
    return term1 + term2

# Define the function h(z)
